import{_ as a,o as t,c as r,a2 as n}from"./chunks/framework.DfDAiEgj.js";const f=JSON.parse('{"title":"智能风控","description":"","frontmatter":{},"headers":[],"relativePath":"ai-finance/AI_Risk_Management.md","filePath":"ai-finance/AI_Risk_Management.md","lastUpdated":null}'),h={name:"ai-finance/AI_Risk_Management.md"};function p(o,e,l,i,s,c){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="智能风控" tabindex="-1">智能风控 <a class="header-anchor" href="#智能风控" aria-label="Permalink to &quot;智能风控&quot;">​</a></h1><p>在传统风控环节中，信息不对称、成本高、时效性差、效率低等问题，使得难以满足业务的快速增长引发的信贷增长。而风控引入人工智能技术，使得贷前审核、贷中监控和贷后管理、监管合规等环节，都能提高金融科技产品质量及服务效率。</p><p>智能风控能不仅能有效提高金融服务的效率和安全性，降低风控成本，还能促进风险管理差异化和业务人性化，在金融科技业中有着重要作用。所以近年来无论是传统金融机构、消费金融机构还是互联网金融公司，都在加紧智能化系统建设或者对外合作，实现智能化风控。</p><p>未来，智能风控要不仅在信贷、反欺诈、异常交易检测等领域发挥作用，充分发挥大数据、人工智能、云计算等综合技术优势，为金融行业欺诈风险的分析和预警监测提供支持，同时也要不断优化数据挖掘采集效率及人工智能算法，同时要实现对各金融机构、金融科技公司数据的标准化，以实现更多的价值场景的快速落地。</p><p>从监管层面，监管机构鼓励金融服务业在风险可控的前提下创新，但随着监管机构加强风险、合规和安全方面的监管，金融服务业需要通过更有效的手段来满足监管要求。<a href="https://www.weiyangx.com/351456.html" target="_blank" rel="noreferrer">1</a></p><p>金融风控解决方案：<a href="https://ecloud.10086.cn/home/solution/finance/risk" target="_blank" rel="noreferrer">https://ecloud.10086.cn/home/solution/finance/risk</a></p><p>风控模型—群体稳定性指标(PSI)深入理解应用：<a href="https://zhuanlan.zhihu.com/p/79682292" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/79682292</a></p><p>蚂蚁金服科技: <a href="https://mp.weixin.qq.com/s/klOGk_3X7QT78w9YPQQzKA" target="_blank" rel="noreferrer">https://mp.weixin.qq.com/s/klOGk_3X7QT78w9YPQQzKA</a></p><p>更多：</p><p><a href="https://www.zhihu.com/people/sun.zhengyang" target="_blank" rel="noreferrer">https://www.zhihu.com/people/sun.zhengyang</a></p><p><a href="https://www.zhihu.com/question/455440996" target="_blank" rel="noreferrer">https://www.zhihu.com/question/455440996</a></p><p>互联网金融中必做的17个模型 - 风控少侠的文章 - 知乎 <a href="https://zhuanlan.zhihu.com/p/384662757" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/384662757</a></p><p>个人征信未来在中国的发展和应用 - King James的文章 - 知乎 <a href="https://zhuanlan.zhihu.com/p/22280599" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/22280599</a></p><p>从目前AI+金融的应用场景市场规模来看，AI风控占据约45%的比重，称得上是目前市场价值最大的应用场景。能够预见，未来AI风控将成为所有金融机构的标配，并将在反欺诈、维护网络安全等领域发挥更做的作用，在金融环境无比复杂的中国，我国的AI风控反超美国，太需要、也太应该了。<a href="https://www.zhihu.com/question/455440996" target="_blank" rel="noreferrer">^2</a></p><p>我们以互联网周刊2021年上半年发布的智能风控企业50强企业为例。</p><p>风控是AI领域里“那块最肥的肉”中的堪称“日本和牛”级别的兼顾强刚需与爆款价值场景。任何一家AI厂商，如果不在风控领域折腾出一些价值场景，好像与其他厂商同场竞技的情况下，底气都没有那么足。</p><p>竞争惨烈，一方面加速促进了AI在风控领域的全场景使用，无论是贷前、贷中还是贷后等各个细分场景中，与传统专家规则、统计分析、商业智能等结合，价值得到了越来越高的体现。<a href="https://ai.51cto.com/art/202107/669280.htm" target="_blank" rel="noreferrer">^3</a></p><h2 id="重要性" tabindex="-1">重要性 <a class="header-anchor" href="#重要性" aria-label="Permalink to &quot;重要性&quot;">​</a></h2><p>2020年10月出台的十四五规划中明确指出,完善现 代金融监管体系,提高金融监管透明度和法治化水平,健全金融风险预防、预警、处 置、问责制度体系,对违法违规行为零容忍。<a href="http://crpe.ruc.edu.cn/CN/article/downloadArticleFile.do?attachType=PDF&amp;id=900" target="_blank" rel="noreferrer">^4</a></p><p>求推荐风控类的书籍？ - 茶尾可妮兔的回答 - 知乎 <a href="https://www.zhihu.com/question/398877221/answer/2222488999" target="_blank" rel="noreferrer">https://www.zhihu.com/question/398877221/answer/2222488999</a></p><p>TODO:</p><p><a href="https://github.com/fgyeason/algorithm-and-risk-management" target="_blank" rel="noreferrer">https://github.com/fgyeason/algorithm-and-risk-management</a><a href="https://blog.csdn.net/dQCFKyQDXYm3F8rB0/article/details/117432876" target="_blank" rel="noreferrer">https://blog.csdn.net/dQCFKyQDXYm3F8rB0/article/details/117432876</a></p>',22)])])}const _=a(h,[["render",p]]);export{f as __pageData,_ as default};
